    def get_market_prices(
        self,
        market_id: MarketId,
        *,
        start: TimestampInput,
        end: TimestampInput,
        resolution: Resolution | None = None,
        fields: Literal["bid", "ask", "mid", "last"]
        | Sequence[Literal["bid", "ask", "mid", "last"]]
        | None = None,
        outcome: Outcome | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> PricesPage:
        """Prices.

        Bid, ask, mid and last trade for each interval, as the interval's close:
        - `bid`, `ask` and `mid`: the state at the end of the interval;
        - `last`: the last trade before the end;
        - intervals with no change repeat the previous values, with `carried: true`;
        - intervals with no data at their end have null values.

        **Availability:**
        - **Kalshi:** 1m and coarser from `bars_1m`'s `available_from` in `GET /v2/venues` (it moves earlier as history is loaded); 1s and 100ms from 17 October 2026.
        - **Polymarket:**
          - 1m and coarser from `bars_1m`'s `available_from` in `GET /v2/venues`, with `mid` only: `bid` and `ask` are null.
          - `last` from `trades`' `available_from` in `GET /v2/venues`: the price of the last trade before the interval's end. A page with `last` ends where both the mid and the trades are available, which can be earlier than the mid alone: leave `last` out of `fields` for the latest mids. Without `last`, `carried` doesn't look at trades: an interval with a trade and no other change is `carried: true`.
          - Markets that closed before `bars_1m`'s `available_from` have no mid; their `last` runs from `trades`' `available_from`, so those that closed before that have neither.
          - 1s and 100ms from `bbo`'s `available_from` in `GET /v2/venues`, with `bid`, `ask` and `mid` from the book. A page there can hold fewer than `limit` points before the window's end, on markets whose book changes very often: keep paging until `next_cursor` is null.

        **Datasets read:** `bars_1m` (1m and coarser); `bbo` and `trades` (1s, 100ms). On Polymarket, `trades` is read only for `last`, at every resolution.

        **Access:** `minute`, or `subminute` for 1s and 100ms. **Cost:** 1 unit per page, or 5 at 1s and 100ms.

        **Streams:** NDJSON or CSV. Resume key: `after=<t>`.

        Args:
            market_id: Venue-qualified market ID. For Polymarket, the part after the colon may also be the slug.
            start: Start of the window, inclusive.
            end: End of the window, exclusive. A time later than now is treated as now, before window limits are checked.
            resolution: Interval length.
            fields: Comma-separated fields to return. Fields not asked for are left out of each row.
            outcome: `yes` (default) or `no`. On markets with other labels (two teams, Over/Under, Up/Down), `yes` is the venue's first-listed outcome; `market.outcomes` in the response names both. The NO view mirrors the YES book: prices become 1 − p, bids and asks swap (so do candle highs and lows), and trade aggressors flip.
            limit: Points per page. Up to 1,000 at 1m and coarser (default 1,000); up to 10,000 at 1s and 100ms (default 10,000).
            cursor: The `next_cursor` from the previous page. Send it with the same parameters.
        """
        return self._request_model(
            "GET",
            "/v2/markets/{market_id}/prices",
            path={"market_id": market_id},
            query=(
                ("start", start, "time"),
                ("end", end, "time"),
                ("resolution", resolution, "scalar"),
                ("fields", fields, "csv"),
                ("outcome", outcome, "scalar"),
                ("limit", limit, "scalar"),
                ("cursor", cursor, "scalar"),
            ),
            model=PricesPage,
        )

