    def get_market_books(
        self,
        market_id: MarketId,
        *,
        at: TimestampInput | None = None,
        start: TimestampInput | None = None,
        end: TimestampInput | None = None,
        interval: Literal["100ms", "1s", "1m", "10m", "1h", "6h", "1d"] | None = None,
        depth: int | Literal["all"] | None = None,
        outcome: Outcome | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> BooksPage:
        """Order books.

        The order book at one millisecond, or sampled on a time grid. Give either `at`, or `start` and `end` (with `interval`), not both.

        - **`at`:** the book with every change at or before `at` applied. `data` holds one book, with `t` = `at`.
        - **`start`, `end`, `interval`:** one book per interval `[t, t + interval)` in the window, as of the interval's end, like prices. Intervals with no data at their end have null `bids` and `asks`.
        - **`last_change`:** the time of the latest change included in each book.

        **Availability:**
        - **Kalshi:** from 17 October 2026, exact to the millisecond.
        - **Polymarket:**
          - At intervals of 1m and coarser, from `book_snapshots`' `available_from` in `GET /v2/venues`: each book is the latest minute book at or before the interval's end. `last_change` is that book's time; the change itself may be earlier.
          - At a millisecond, or below 1m: from `book_updates`' `available_from` in `GET /v2/venues`. `last_change` there can be earlier or later than the book's latest real change: for exact times, use `book-updates`.

        **Datasets read:** `book_snapshots`, `book_updates`.

        **Access:** `minute` for intervals of 1m and coarser; `subminute` for `at` and for intervals below 1m. **Cost:** 1 unit per page; 5 for `at` and below 1m.

        **Limits:** a page holds up to `limit` books and stops at 100,000 price levels. Below 1m, the window is ≤ 6 h and ≤ 100,000 intervals. On Polymarket below 1m, a page can also stop sooner, on markets whose book changes very often.

        **Streams:** NDJSON only. Resume key: `after=<t>`.

        Args:
            market_id: Venue-qualified market ID. For Polymarket, the part after the colon may also be the slug.
            at: One book at this instant. Not with `start`, `end` or `interval`.
            start: Start of the grid (with `end`). Not with `at`.
            end: End of the grid, exclusive (with `start`). Not with `at`.
            interval: Interval length, with `start` and `end` (1m if omitted). Not with `at`.
            depth: Price levels per side, best first, or `all`.
            outcome: `yes` (default) or `no`. On markets with other labels (two teams, Over/Under, Up/Down), `yes` is the venue's first-listed outcome; `market.outcomes` in the response names both. The NO view mirrors the YES book: prices become 1 − p, bids and asks swap (so do candle highs and lows), and trade aggressors flip.
            limit: Books per page.
            cursor: The `next_cursor` from the previous page. Send it with the same parameters.
        """
        return self._request_model(
            "GET",
            "/v2/markets/{market_id}/books",
            path={"market_id": market_id},
            query=(
                ("at", at, "time"),
                ("start", start, "time"),
                ("end", end, "time"),
                ("interval", interval, "scalar"),
                ("depth", depth, "scalar"),
                ("outcome", outcome, "scalar"),
                ("limit", limit, "scalar"),
                ("cursor", cursor, "scalar"),
            ),
            model=BooksPage,
        )

