class AsyncOperations(AsyncBase):
    """The operations as coroutines; ``iter_*`` and ``stream_*`` return async iterables."""

    async def get_health(
        self,
    ) -> HealthResponse:
        """Health.

        Whether the API can serve requests. Needs no key and costs nothing. Returns 503 when it can't.
        """
        return await self._request_model(
            "GET",
            "/v2/health",
            path={},
            model=HealthResponse,
            accept=(503,),
        )

    async def get_usage(
        self,
    ) -> UsageResponse:
        """Usage, entitlements and quotas.

        Your organisation's plan, rate limit, access per venue and dataset, and monthly quotas with what's used so far.

        **Access:** any key. **Cost:** 1 unit.
        """
        return await self._request_model(
            "GET",
            "/v2/usage",
            path={},
            model=UsageResponse,
        )

    async def list_venues(
        self,
    ) -> VenueList:
        """Venues and their datasets.

        Every venue, the datasets it provides, from when each one is available, and the attribution its data must carry.

        **Access:** any key. **Cost:** 1 unit.
        """
        return await self._request_model(
            "GET",
            "/v2/venues",
            path={},
            model=VenueList,
        )

    async def list_categories(
        self,
    ) -> CategoryList:
        """Categories.

        Our category taxonomy, used by the `category` filter on every venue, and the venue categories each one includes.

        **Access:** any key. **Cost:** 1 unit.
        """
        return await self._request_model(
            "GET",
            "/v2/categories",
            path={},
            model=CategoryList,
        )

    async def list_series(
        self,
        *,
        venue: Venue | Sequence[Venue] | None = None,
        category: str | None = None,
        search: str | None = None,
        ids: str | Sequence[str] | None = None,
        updated_since: TimestampInput | None = None,
        sort: Literal["updated_at", "created_at"] | None = None,
        order: Literal["asc", "desc"] | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> SeriesList:
        """List series.

        Series (recurring groups of events, such as a monthly Fed decision) on the venues you can access.

        Without `venue`, the list covers every venue your key can read.

        **Access:** `reference` for each venue listed. **Cost:** 1 unit per page.

        Args:
            venue: Only these venues (repeat the parameter for several). Defaults to every venue your key can read.
            category: One of our category codes (`GET /v2/categories`).
            search: Words to find in titles, slugs and tickers.
            ids: Comma-separated venue-qualified IDs, up to 100.
            updated_since: Only items whose `updated_at` is at or after this time.
            sort: Sort field. With `search`, results are sorted by relevance instead.
            order:
            limit: Items per page.
            cursor: The `next_cursor` from the previous page. Send it with the same parameters.
        """
        return await self._request_model(
            "GET",
            "/v2/series",
            path={},
            query=(
                ("venue", venue, "repeat"),
                ("category", category, "scalar"),
                ("search", search, "scalar"),
                ("ids", ids, "csv"),
                ("updated_since", updated_since, "time"),
                ("sort", sort, "scalar"),
                ("order", order, "scalar"),
                ("limit", limit, "scalar"),
                ("cursor", cursor, "scalar"),
            ),
            model=SeriesList,
        )

