                ("category", category, "scalar"),
                ("status", status, "repeat"),
                ("series", series, "scalar"),
                ("search", search, "scalar"),
                ("ids", ids, "csv"),
                ("open_from", open_from, "time"),
                ("open_to", open_to, "time"),
                ("close_from", close_from, "time"),
