    async def get_market(
        self,
        market_id: MarketId,
        *,
        as_of: TimestampInput | None = None,
    ) -> MarketResponse:
        """Market details.

        Everything we hold about one market: rules, outcome labels, tick structure, times, settlement, the venue's own IDs and venue-specific fields.

        With `as_of`, you get the metadata as it was at that time (Kalshi only for now; on Polymarket it returns `invalid_parameter`):
        - Metadata history is available from 17 October 2026.
        - If `as_of` is before the market's first available version (always the case before 17 October 2026), you get that first version, so the details at `as_of` may have been different.

        **Access:** `reference` for the venue. **Cost:** 1 unit.

        Args:
            market_id: Venue-qualified market ID. For Polymarket, the part after the colon may also be the slug.
            as_of: Kalshi only: return the metadata as it was at this time (available from 17 October 2026).
        """
        return await self._request_model(
            "GET",
            "/v2/markets/{market_id}",
            path={"market_id": market_id},
            query=(("as_of", as_of, "time"),),
            model=MarketResponse,
        )

