    def stream_market_prices(
        self,
        market_id: MarketId,
        *,
        start: TimestampInput,
        end: TimestampInput,
        resolution: Resolution | None = None,
        fields: Literal["bid", "ask", "mid", "last"]
        | Sequence[Literal["bid", "ask", "mid", "last"]]
        | None = None,
        outcome: Outcome | None = None,
        after: TimestampInput | None = None,
        format: Literal["ndjson", "csv"] = "ndjson",
        max_resumes: int = 10,
    ) -> AsyncStream[PricePoint]:
        """Stream every PricePoint in the window as NDJSON or CSV: one request, however many rows.

        If the connection breaks, the stream resumes by itself after the last row received (``after=<t>``), so no row is repeated or skipped; once rows flow, it waits out an outage. Before the first row, the client's ``max_retries`` applies and the API's own error is raised. It costs what one page costs; tick rows count against your monthly quota. ``.to_pandas()`` reads it into a DataFrame and ``.save(path)`` writes it to a file.

        Args:
            market_id: Venue-qualified market ID. For Polymarket, the part after the colon may also be the slug.
            start: Start of the window, inclusive.
            end: End of the window, exclusive. A time later than now is treated as now, before window limits are checked.
            resolution: Interval length.
            fields: Comma-separated fields to return. Fields not asked for are left out of each row.
            outcome: `yes` (default) or `no`. On markets with other labels (two teams, Over/Under, Up/Down), `yes` is the venue's first-listed outcome; `market.outcomes` in the response names both. The NO view mirrors the YES book: prices become 1 − p, bids and asks swap (so do candle highs and lows), and trade aggressors flip.
            after: Streams only: resume after the interval starting at this time (the last row's `t`).
            format: `ndjson` (rows as models) or `csv` (the fastest way into pandas or a file).
            max_resumes: Once rows flow, failures in a row (breaks or failed requests, no new row between them) before APIConnectionError is raised; a new row resets the count.
        """
        return self._stream(
            "/v2/markets/{market_id}/prices",
            path={"market_id": market_id},
            query=(
                ("start", start, "time"),
                ("end", end, "time"),
                ("resolution", resolution, "scalar"),
                ("fields", fields, "csv"),
                ("outcome", outcome, "scalar"),
            ),
            row=PricePoint,
            key=("t",),
            formats=("ndjson", "csv"),
            format=format,
            after=after,
            max_resumes=max_resumes,
        )

    async def get_market_candles(
        self,
        market_id: MarketId,
        *,
        start: TimestampInput,
        end: TimestampInput,
        resolution: Resolution | None = None,
        basis: Literal["mid", "trade"] | None = None,
        outcome: Outcome | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> CandlesPage:
        """Candles.

        Open, high, low and close for each interval, with volume, trade count and VWAP.

        **`basis`:**
        - `mid` (default): the OHLC is of the mid price;
        - `trade`: the OHLC is of trade prices.

        Volume, trades and VWAP always come from trades, and are null where the venue's trades aren't available.

        **Empty intervals:** they repeat the previous close with zero volume and `carried: true`. Intervals with no data at their end are null.

        **Availability:** as for prices.
        - **Kalshi:** trade candles from `trades`' `available_from` in `GET /v2/venues`; before 16:16 UTC on 17 October 2026, mid `high` and `low` may be null. Before 18 October 2026, a trade candle's `open` and `close` follow the order of trades that share a `ts`, so they can differ from the first and last trade executed.
        - **Polymarket:** trade candles, volume, trades and VWAP from `trades`' `available_from` in `GET /v2/venues`. Each trade is the fill of one maker order (see `trades`): a taker order that fills three resting orders counts as three trades, and volume counts each share once. Mid candles end where both the mid and the trades are available; trade candles where the trades are. Markets that closed before `bars_1m`'s `available_from` have mid candles with a null open, high, low and close; their trade candles, volume, trades and VWAP run from `trades`' `available_from`. At 1s and 100ms a page can hold fewer than `limit` candles before the window's end, as for prices.

        **Datasets read:** `bars_1m`, `trades`; `bbo` at 1s and 100ms.

        **Access:** `minute`, or `subminute` for 1s and 100ms. **Cost:** 1 unit per page, or 5 at 1s and 100ms.

        **Streams:** NDJSON or CSV. Resume key: `after=<t>`.

        Args:
            market_id: Venue-qualified market ID. For Polymarket, the part after the colon may also be the slug.
            start: Start of the window, inclusive.
            end: End of the window, exclusive. A time later than now is treated as now, before window limits are checked.
            resolution: Interval length.
            basis: Price the OHLC is built from.
            outcome: `yes` (default) or `no`. On markets with other labels (two teams, Over/Under, Up/Down), `yes` is the venue's first-listed outcome; `market.outcomes` in the response names both. The NO view mirrors the YES book: prices become 1 − p, bids and asks swap (so do candle highs and lows), and trade aggressors flip.
            limit: Points per page. Up to 1,000 at 1m and coarser (default 1,000); up to 10,000 at 1s and 100ms (default 10,000).
            cursor: The `next_cursor` from the previous page. Send it with the same parameters.
        """
        return await self._request_model(
            "GET",
            "/v2/markets/{market_id}/candles",
            path={"market_id": market_id},
            query=(
                ("start", start, "time"),
                ("end", end, "time"),
                ("resolution", resolution, "scalar"),
                ("basis", basis, "scalar"),
                ("outcome", outcome, "scalar"),
                ("limit", limit, "scalar"),
                ("cursor", cursor, "scalar"),
            ),
            model=CandlesPage,
        )

